import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return (x1 + 1)**2 + (x2 - 0.5)**2 + 0.1 * x1 * np.cos(x1 * x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.5 * (x1**2 + x2**2 + 0.2 * x1 * x2) + 0.2 * (x1 + x2) + 0.1 * np.exp(-0.5 * ((x1 - 1)**2 + (x2 + 1)**2)) + 0.05 * x1**3 + 0.1 * np.arctan(x2))
